    return {"kind": "plot", "x": [0, 'tau * 1.25'], "y": [0, 't2 * 1.2'], "lines": [{"points": [[0, 't1'], ['tau', 't2']]}], "axes": {"x": 'τ, мин', "y": 't, °C'}}

